from calc import divide

def test_divide():
    assert divide(4, 2) == 2
    assert divide(-3, 2) == -1.5
    try:
        result = divide(1, 0)
    except ZeroDivisionError:
        result = object()
    assert result is None, 'divide(a, 0) must return None'

if __name__ == '__main__':
    test_divide()
